<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { api, type Data } from '../api/client'
import { useRequest } from '../composables/useRequest'
import { confirmAction, statusText } from '../lib/ui'
import PageHeader from '../components/PageHeader.vue'
import Icon from '../components/Icon.vue'
import EmptyState from '../components/EmptyState.vue'
import StructuredResult from '../components/StructuredResult.vue'
const { run, busy, error } = useRequest(); const goal = ref('帮我安排这周的数据库学习计划'); const agents = ref<Data[]>([]); const selected = ref<Data | null>(null); const calls = ref<Data[]>([]); const token = ref(''); const planHash = ref(''); const report = ref<Data | null>(null); const expandedLog = ref<Data | null>(null); const loaded = ref(false)
const statuses: Record<string, string> = { pending_confirmation: '待确认', running: '执行中', completed: '已完成', cancelled: '已取消', failed: '执行失败' }
const current = computed(() => agents.value.find(x => x.id === selected.value?.id) || selected.value)
async function refresh() { agents.value = await api.get<Data[]>('/agent/tasks'); loaded.value = true; if (selected.value) selected.value = agents.value.find(x => x.id === selected.value?.id) || null }
async function load() { await run(refresh) }
async function create() { await run(async () => { const result = await api.post('/agent/tasks', { goal: goal.value }); token.value = result.confirmation_token || ''; planHash.value = result.plan_hash || result.plan?.plan_hash || ''; selected.value = result; await refresh(); selected.value = agents.value.find(x => x.id === result.id) || result; await loadCalls(result.id) }, '计划已生成，请检查后确认') }
async function confirm() { const id = current.value?.id; if (!id) return; if (!token.value || !planHash.value) { await refreshToken(); return }; if (!await confirmAction('确认后 Agent 将只创建计划中列出的学习任务，不执行其他系统操作。', '确认执行')) return; await run(async () => { const result = await api.post(`/agent/tasks/${id}/confirm`, { confirmation_token: token.value, plan_hash: planHash.value }); selected.value = result; token.value = ''; planHash.value = ''; await refresh(); await loadCalls(id) }, 'Agent 已执行，结果已写入日志') }
async function refreshToken() { const id = current.value?.id; if (!id) return; await run(async () => { const result = await api.post(`/agent/tasks/${id}/confirmation`); token.value = result.confirmation_token; planHash.value = result.plan_hash }, '已刷新确认凭证，请再次确认计划') }
async function cancel() { const id = current.value?.id; if (!id || !await confirmAction('取消后不会创建计划任务。')) return; await run(async () => { await api.post(`/agent/tasks/${id}/cancel`); await refresh(); await loadCalls(id) }, 'Agent 已取消') }
function parseJson(value: unknown) { if (typeof value !== 'string') return value; try { return JSON.parse(value) } catch { return value } }
async function loadCalls(id: string) { const data = await api.get<Data[]>(`/agent/tasks/${id}/calls`); calls.value = data.map(item => ({ ...item, input: parseJson(item.input_json), output: parseJson(item.output_json) })) }
async function view(item: Data) { token.value = ''; planHash.value = ''; await run(async () => { selected.value = await api.get(`/agent/tasks/${item.id}`); await loadCalls(item.id) }) }
async function makeReport(period: 'daily' | 'weekly') { await run(async () => { report.value = await api.post('/reports', { period }) }, '报告已生成；内容基于真实记录') }
function planActions(item: Data) { return item?.plan?.actions || item?.plan?.steps || [] }
onMounted(load)
</script>
<template><section class="page">
  <PageHeader title="智能行动" eyebrow="先审阅，再让 Agent 执行" description="AI 只能规划并创建当前账户的学习任务；计划、凭证、工具调用和结果都可查看"><RouterLink class="secondary" to="/learning"><Icon name="check" :size="17" /> 查看任务</RouterLink><button class="primary" :disabled="busy" @click="create"><Icon name="agent" :size="17" /> 生成行动计划</button></PageHeader>
  <div v-if="error" class="error-banner" role="alert">{{ error }}<button class="text-button" :disabled="busy" @click="load">重试</button></div><section class="agent-compose panel"><div class="agent-mark"><Icon name="agent" :size="28" /></div><div class="grow"><h2>你希望这次学习发生什么？</h2><p>Agent 会读取你的学习上下文，生成待确认的 create_task 动作。</p><form class="agent-input" @submit.prevent="create"><input v-model="goal" maxlength="2000" :disabled="busy" placeholder="例如：在下周考试前复习操作系统重点" /><button class="primary" :disabled="busy || !goal.trim()">{{ busy ? '正在分析…' : '生成计划 →' }}</button></form></div></section><div class="agent-flow"><div><span>01</span><strong>理解目标</strong><small>读取学习上下文</small></div><i>→</i><div><span>02</span><strong>展示计划</strong><small>动作清晰可审阅</small></div><i>→</i><div><span>03</span><strong>你来确认</strong><small>凭证一次性使用</small></div><i>→</i><div><span>04</span><strong>执行并记录</strong><small>每一步留下日志</small></div></div><div class="agent-layout"><section class="agent-history panel"><div class="panel-head"><div><h2>行动记录</h2><p>最新计划在上方</p></div><span class="count-badge">{{ agents.length }}</span></div><button v-for="item in agents" :key="item.id" class="history-item" :class="{ selected: current?.id === item.id }" :disabled="busy" @click="view(item)"><span class="status-dot" :class="item.status"></span><div><strong>{{ item.goal }}</strong><small>{{ statuses[item.status] || item.status }} · {{ new Date(item.created_at).toLocaleString('zh-CN') }}</small></div><Icon name="arrow" :size="15" /></button><EmptyState v-if="!agents.length && loaded" title="还没有行动计划" description="把一个学习目标写进上方输入框。" icon="agent" /></section><section v-if="current" class="agent-detail panel"><div class="panel-head"><div><span class="eyebrow">{{ statuses[current.status] || current.status }}</span><h2>{{ current.goal }}</h2></div><div class="button-row"><button v-if="current.status === 'pending_confirmation'" class="secondary small" :disabled="busy" @click="refreshToken">刷新凭证</button><button v-if="['pending_confirmation', 'running'].includes(current.status)" class="danger small" :disabled="busy" @click="cancel">取消</button></div></div><div class="safety-note"><Icon name="shield" /><span>安全边界：仅创建当前用户的学习任务；不删除资源、不执行命令、不读取任意文件。</span></div><div class="action-list"><div v-for="(action, index) in planActions(current)" :key="action.title || index" class="action-row"><span>{{ String(Number(index) + 1).padStart(2, '0') }}</span><div class="grow"><strong>{{ action.title || action.name || action.type }}</strong><p>{{ action.description || action.input || 'Agent 规划的学习行动' }}</p><small>{{ action.estimated_minutes || action.minutes || '—' }} 分钟 <template v-if="action.due_date">· {{ action.due_date }}</template></small></div></div><EmptyState v-if="!planActions(current).length" title="没有可展示的动作" description="服务返回的计划不含动作列表。" icon="agent" /></div><div v-if="current.status === 'pending_confirmation'" class="confirm-box"><strong>确认后才会写入任务</strong><p>确认凭证只在当前响应中返回；如果页面刷新，可以使用“刷新凭证”重新生成并再次核对计划。</p><button class="primary" :disabled="busy || !token" @click="confirm">{{ busy ? '正在执行…' : token ? '确认执行这些动作' : '刷新凭证后确认' }}</button></div><div v-if="current.result" class="result-box"><strong>执行结果</strong><pre>{{ JSON.stringify(current.result, null, 2) }}</pre></div><div v-if="calls.length" class="logs"><div class="panel-head"><h3>工具调用日志</h3><span class="muted">{{ calls.length }} 条</span></div><button v-for="log in calls" :key="log.id" class="log-row" @click="expandedLog = expandedLog?.id === log.id ? null : log"><span class="status-dot" :class="log.status"></span><span class="grow"><strong>{{ log.tool_name }}</strong><small>{{ new Date(log.created_at).toLocaleString('zh-CN') }}</small></span><Icon name="arrow" :size="15" /></button><pre v-if="expandedLog" class="json-result">{{ JSON.stringify(expandedLog, null, 2) }}</pre></div></section><EmptyState v-else title="每一次自动化，都应该可控" description="生成计划后，你会看到完整的动作与安全边界。" icon="shield" /></div><section class="panel report-quick"><div class="panel-head"><div><h2>快速生成数据报告</h2><p>报告没有动作权限，只读取真实统计并标注来源。</p></div><div class="button-row"><button class="secondary small" :disabled="busy" @click="makeReport('daily')">今日报告</button><button class="secondary small" :disabled="busy" @click="makeReport('weekly')">本周报告</button></div></div><div v-if="report" class="report-preview"><div class="meta-row"><span class="pill">{{ report.source === 'ai' ? 'AI 总结' : '数据摘要' }}</span><span>{{ report.title }}</span></div><p>{{ report.content }}</p><RouterLink class="text-button" to="/analytics">在数据中心查看 →</RouterLink></div></section>
</section></template>
